theorem fixed (tm : FinTM2) (e : tm.Γ tm.k₀ ≃ Bool) {σ : Vocabulary} {m : Nat}
    (d : Nat) (A : PointedStructure σ m) :
    ParameterizedRules.operator (rules tm e σ m d) A.structureValue A.tuple (closure tm e d A) = closure tm e d A

theorem configuration_injective {t s : Nat}
    {c e : NodeMachine.Cfg tm.Γ tm.Λ tm.σ (TimedNodes.Node Initial)}
    (hc : Valid tm (n ^ d) (.config t c)) (he : Valid tm (n ^ d) (.config s e))
    (h : configuration P t c = configuration P s e) : t = s ∧ c = e

theorem relationDiagram_firstOrder {σ : Vocabulary} {m n : Nat}
    (r : Symbol σ) (a : Fin (σ.get r) → Fin n) (b : Bool) :
    FirstOrder (relationDiagram (m := m) r a b)

theorem satisfies_boundedFormula {σ : Vocabulary} {k : Nat}
    (Q : Query σ k) (N : Nat) (A : PointedStructure σ k) :
    Satisfies A (boundedFormula Q N) ↔ A.structureValue.size ≤ N ∧ Q A

theorem correct_conj {φ ψ : RawFormula σ m ρ}
    (hφ : Correct (K := K) (Aux := Aux) φ) (hψ : Correct (K := K) (Aux := Aux) ψ) :
    Correct (K := K) (Aux := Aux) (.conj φ ψ)

theorem correct_lfp {body : RawFormula σ (k + m) (k :: ρ)}
    (hbody : Correct (K := K) (Aux := Aux) body) (args : Fin k → Fin m) :
    Correct (K := K) (Aux := Aux) (.lfp k body args)

theorem firstOrder_rename {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (φ : RawFormula σ m ρ) {l : Nat} (f : Fin m → Fin l) :
    FirstOrder (rename φ f) ↔ FirstOrder φ

theorem firstOrder_allOf {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (fs : List (RawFormula σ m ρ)) :
    FirstOrder (allOf fs) ↔ ∀ φ ∈ fs, FirstOrder φ

theorem firstOrder_anyOf {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (fs : List (RawFormula σ m ρ)) :
    FirstOrder (anyOf fs) ↔ ∀ φ ∈ fs, FirstOrder φ

theorem copyFO_positive {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (φ : RawFormula σ m ρ) (τ : List Nat) (r : Fin τ.length) (p : Bool) :
    (copyFO φ τ).positiveAt r p

theorem positive_allOf {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (fs : List (RawFormula σ m ρ)) (r : Fin ρ.length) (p : Bool) :
    (allOf fs).positiveAt r p ↔ ∀ φ ∈ fs, φ.positiveAt r p

theorem positive_anyOf {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (fs : List (RawFormula σ m ρ)) (r : Fin ρ.length) (p : Bool) :
    (anyOf fs).positiveAt r p ↔ ∀ φ ∈ fs, φ.positiveAt r p

theorem Represents.of_stacks {input : Inputs K σ m ρ} {A : OrderedStructure σ}
    {v : Fin m → Fin A.size} {η : TableEvaluation.TableEnv A.size ρ} {s t : EvalStore K Aux}
    (h : Represents input A v η s) (hs : t.stk = s.stk) : Represents input A v η t

theorem Represents.result {input : Inputs K σ m ρ} {A : OrderedStructure σ}
    {v : Fin m → Fin A.size} {η : TableEvaluation.TableEnv A.size ρ} {s : EvalStore K Aux}
    (h : Represents input A v η s) (b : Bool) : Represents input A v η (result b s)

theorem Represents.frame {input : Inputs K σ m ρ} {A : OrderedStructure σ}
    {v : Fin m → Fin A.size} {η : TableEvaluation.TableEnv A.size ρ} {s t : EvalStore K Aux}
    (h : Represents input A v η s) (hs : ∀ key, ¬ input.Fresh key → t.stk key = s.stk key) :
    Represents input A v η t

theorem Represents.setStack {input : Inputs K σ m ρ} {A : OrderedStructure σ}
    {v : Fin m → Fin A.size} {η : TableEvaluation.TableEnv A.size ρ} {s : EvalStore K Aux}
    (h : Represents input A v η s) {key : K} (hf : input.Fresh key) (bits : List Bool) :
    Represents input A v η (StackTuples.setStack s key bits)

theorem Represents.saved {input : Inputs K σ m ρ} {A : OrderedStructure σ}
    {v : Fin m → Fin A.size} {η : TableEvaluation.TableEnv A.size ρ} {s : EvalStore K Aux}
    (h : Represents input A v η s) {key : K} (hf : input.Fresh key) (b : Bool) :
    Represents input A v η (saved key b s)

theorem Represents.existsPorts {input : Inputs K σ m ρ} {A : OrderedStructure σ}
    {v : Fin m → Fin A.size} {η : TableEvaluation.TableEnv A.size ρ} {s : EvalStore K Aux}
    (h : Represents input A v η s) (coordinate : K) (a : Fin A.size)
    (hc : s.stk coordinate = List.replicate a.val true) :
    Represents (input.existsPorts coordinate) A (Fin.cons a v) η s

theorem Clean.setStack {W : Type} {work : W → K} {s : EvalStore K Aux}
    (h : Clean work s) (key : K) (hf : ∀ w, work w ≠ key) (bits : List Bool) :
    Clean work (StackTuples.setStack s key bits)

theorem Clean.saved {W : Type} {work : W → K} {s : EvalStore K Aux}
    (h : Clean work s) (key : K) (hf : ∀ w, work w ≠ key) (b : Bool) :
    Clean work (saved key b s)

theorem fresh_code {Initial : Type} {iWidth : Nat}
    (P : FactCodes.Parameters tm Initial n iWidth d w) (t : Nat) :
    fresh (w := w) ⟨0, by have

theorem assignment_pattern {tm : FinTM2} {σ : Vocabulary} {m n d w : Nat}
    (hn : MachineConstants.bound tm ≤ n) (a : Fin (numVars σ m d) → Fin n) :
    assignment hn a ∘ pattern tm σ m d w = value (w := w) hn (a ∘ time σ m d) (a ∘ position σ m d)

theorem window_firstOrder {σ : Vocabulary} {m v w : Nat} {ρ : List Nat}
    (hw : ∀ s : Segment σ m, s.arity ≤ w) (query : Fin m → Fin v)
    (lo hi : Option (Fin (w + 1) → Fin v)) : FirstOrder (window (ρ := ρ) hw query lo hi)

theorem first_firstOrder {σ : Vocabulary} {m v w : Nat} {ρ : List Nat}
    (hw : ∀ s : Segment σ m, s.arity ≤ w) (query : Fin m → Fin v)
    (x : Fin (w + 1) → Fin v) : FirstOrder (first (ρ := ρ) hw query x)

theorem last_firstOrder {σ : Vocabulary} {m v w : Nat} {ρ : List Nat}
    (hw : ∀ s : Segment σ m, s.arity ≤ w) (query : Fin m → Fin v)
    (x : Fin (w + 1) → Fin v) : FirstOrder (last (ρ := ρ) hw query x)

theorem next_firstOrder {σ : Vocabulary} {m v w : Nat} {ρ : List Nat}
    (hw : ∀ s : Segment σ m, s.arity ≤ w) (query : Fin m → Fin v)
    (x y : Fin (w + 1) → Fin v) : FirstOrder (next (ρ := ρ) hw query x y)

theorem position_firstOrder {σ : Vocabulary} {m v w : Nat} {ρ : List Nat}
    (hw : ∀ s : Segment σ m, s.arity ≤ w) (query : Fin m → Fin v)
    (addr : Fin (w + 1) → Fin v) : FirstOrder (position (ρ := ρ) hw query addr)

theorem valid_firstOrder {σ : Vocabulary} {m v : Nat} {ρ : List Nat}
    (query : Fin m → Fin v) (s : Segment σ m) (x : Fin s.arity → Fin v) :
    FirstOrder (valid (ρ := ρ) query s x)

theorem symbol_firstOrder {σ : Vocabulary} {m v : Nat} {ρ : List Nat}
    (s : Segment σ m) (x : Fin s.arity → Fin v) :
    FirstOrder (symbol (ρ := ρ) s x)

theorem cast_state (tm : FinTM2) {n : Nat} (hn : bound tm ≤ n) (v : tm.σ) :
    Fin.castLE hn (state tm v) =
      @TupleCoding.finiteCode tm.σ tm.σFin n ((states_bound tm).trans hn) v

theorem step_mono {M : Λ → TM2.Stmt Γ Λ State} {fresh : Node} {H G J : Records Node Γ}
    {c d : Cfg Γ Λ State Node} (h : Step M fresh H c G d) (hHJ : H ⊆ J) :
    ∃ J', Step M fresh J c J' d ∧ G ⊆ J'

theorem step_unique {M : Λ → TM2.Stmt Γ Λ State} {fresh : Node} {H G J : Records Node Γ}
    {c d e : Cfg Γ Λ State Node} (hF : Functional H)
    (hd : Step M fresh H c G d) (he : Step M fresh H c J e) : G = J ∧ d = e

theorem step_records {M : Λ → TM2.Stmt Γ Λ State} {fresh : Node} {H G : Records Node Γ}
    {c d : Cfg Γ Λ State Node} (h : Step M fresh H c G d) (r : Node × Sigma Γ × Option Node) :
    r ∈ G ↔ r ∈ H ∨ added fresh c = some r

theorem step_linked {M : Λ → TM2.Stmt Γ Λ State} {fresh : Node} {H G : Records Node Γ}
    {c d : NodeMachine.Cfg Γ Λ State Node} (hs : Step M fresh H c G d)
    (hH : Linked H) (hc : ∀ k, Known H (c.heads k)) : Linked G

theorem length_executes {Γ : K → Type} {State : Type} {p : Program Γ State}
    {s t : Store Γ State} {c : Nat} (h : Executes p s t c) (key : K) :
    (t.stk key).length ≤ (s.stk key).length + c

theorem runs_trans [DecidableEq K] {Λ : Type} {code : Λ → TM2.Stmt Γ Λ σ}
    {l m n : Option Λ} {s u t : Store Γ σ} {a b : Nat}
    (h : Runs code l s m u a) (h' : Runs code m u n t b) :
    Runs code l s n t (a + b)

theorem executes_in_sum {p : Program (fun _ : K => Γ) σ} {s t : Store (fun _ : K => Γ) σ}
    {cost : Nat} (h : Executes p s t cost) (extra : L → List Γ) :
    Executes (rename Sum.inl p) (sumStore s extra) (sumStore t extra) cost

theorem rename_admissible {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (φ : RawFormula σ m ρ) {l : Nat} (f : Fin m → Fin l) :
    (rename φ f).Admissible ↔ φ.Admissible

theorem evals_valid (tm : FinTM2) (xs : List (tm.Γ tm.k₀)) {d : tm.Cfg} {T : Nat}
    (h : StateTransition.EvalsToInTime tm.step (initList tm xs) (some d) T) :
    Valid (alphabet tm : Set (Sigma tm.Γ)) d.stk

theorem macro_matches (M : Λ → TM2.Stmt Γ Λ State) (n : Nat) {c d : TM2.Cfg Γ Λ State}
    (h : (fun q : Option (TM2.Cfg Γ Λ State) => q.bind (TM2.step M))^[n] (some c) = some d) :
    (macroNext M)^[n] c = d

theorem evals_refines (tm : FinTM2) {c d : tm.Cfg} {T : Nat}
    (h : StateTransition.EvalsToInTime tm.step c (some d) T) :
    ∃ t, t ≤ factor tm * T ∧ (next tm.m)^[t] (boundary c) = boundary d

theorem evals_at_time (tm : FinTM2) {c d : tm.Cfg} {T N : Nat}
    (h : StateTransition.EvalsToInTime tm.step c (some d) T) (hd : d.l = none)
    (hN : factor tm * T ≤ N) : (next tm.m)^[N] (boundary c) = boundary d

theorem instruction_sub (tm : FinTM2) {p q : TM2.Stmt tm.Γ tm.Λ tm.σ}
    (hq : Cursor.instruction q ∈ controls tm) (hp : p ∈ TM2.stmts₁ q) :
    Cursor.instruction p ∈ controls tm

theorem step_bounded {M : Λ → TM2.Stmt Γ Λ State} {t : Nat} {H G : Records (Node Initial) Γ}
    {c d : NodeMachine.Cfg Γ Λ State (Node Initial)} (h : Step M (.inr t) H c G d) (hH : Bounded H t) :
    Bounded G (t + 1)

theorem run_sound {M : Λ → TM2.Stmt Γ Λ State} {H₀ H : Records (Node Initial) Γ}
    {c₀ c : NodeMachine.Cfg Γ Λ State (Node Initial)} {t : Nat}
    (h : Run M H₀ c₀ t H c) (hF : Functional H₀) (hB : Bounded H₀ 0)
    (d₀ : TM2Micro.Cfg Γ Λ State) (hM : Matches H₀ c₀ d₀) :
    Functional H ∧ Bounded H t ∧ Matches H c ((TM2Micro.next M)^[t] d₀)

theorem run_unique {M : Λ → TM2.Stmt Γ Λ State} {H₀ H G : Records (Node Initial) Γ}
    {c₀ c d : NodeMachine.Cfg Γ Λ State (Node Initial)} {t : Nat}
    (hF : Functional H₀) (hB : Bounded H₀ 0) (d₀ : TM2Micro.Cfg Γ Λ State) (hM : Matches H₀ c₀ d₀)
    (hc : Run M H₀ c₀ t H c) (hd : Run M H₀ c₀ t G d) : H = G ∧ c = d

theorem finiteGuard_firstOrder {σ : Vocabulary} {v : Nat} {ρ : List Nat}
    {α : Type} [Fintype α] (c : α) (x : Fin v) :
    FormulaMacros.FirstOrder (finiteGuard (σ := σ) (ρ := ρ) c x)

theorem admissible_allOf {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (fs : List (RawFormula σ m ρ)) :
    (allOf fs).Admissible ↔ ∀ φ ∈ fs, φ.Admissible

theorem admissible_anyOf {σ : Vocabulary} {m : Nat} {ρ : List Nat}
    (fs : List (RawFormula σ m ρ)) :
    (anyOf fs).Admissible ↔ ∀ φ ∈ fs, φ.Admissible
